#include "elit21/shopify/webhooks/ShopifyWebhookDispatcher.h"
namespace elit21::shopify::webhooks {ShopifyWebhookDispatcher::ShopifyWebhookDispatcher():platform::BusinessComponent("ShopifyWebhookDispatcher","Topic-routed Shopify webhook dispatcher",platform::BusinessComponentSpec{"shopify","dispatch_webhook",{},true,false,16U*1024U*1024U}){}void ShopifyWebhookDispatcher::registerHandler(ShopifyWebhookTopic topic,Handler handler){if(topic!=ShopifyWebhookTopic::unknown&&handler)handlers_[topic]=std::move(handler);}Result<void>ShopifyWebhookDispatcher::dispatch(const ShopifyWebhook&e)const{auto valid=e.validate();if(!valid)return valid;auto it=handlers_.find(e.topic());if(it==handlers_.end())return Result<void>::failure("No Shopify webhook handler for "+topicName(e.topic()));return it->second(e);}platform::OperationResult ShopifyWebhookDispatcher::execute(const platform::OperationContext&context){auto r=executeBusiness(context);r.metrics["registered_handlers"]=static_cast<double>(handlers_.size());return r;}}
